def get_employee_record_update_request_client_scripts():
	return [
		{
			"name": "Employee Record Update",
			"dt": "Employee Record Update Request",
			"view": "Form",
			"enabled": 0,
			"script": "frappe.ui.form.on('Employee Record Update Request', {\n    refresh: function(frm) {\n        set_new_value_options(frm);\n    }\n});\n\n// Triggered when selecting or changing the Property in a child table row\nfrappe.ui.form.on('Employee Record Update Request Properties Item', { // Replace with exact Child Table DocType name\n    property: function(frm, cdt, cdn) {\n        var row = locals[cdt][cdn];\n        \n        // Clear previous value when property changes\n        frappe.model.set_value(cdt, cdn, 'new_value', '');\n        \n        set_row_value_options(frm, cdt, cdn);\n    },\n    \n    properties_add: function(frm, cdt, cdn) { // Replace properties_table with actual table fieldname\n        set_row_value_options(frm, cdt, cdn);\n    }\n});\n\nfunction set_new_value_options(frm) {\n    if (frm.doc.properties) { // Replace properties with your table fieldname\n        frm.doc.properties.forEach(function(row) {\n            set_row_value_options(frm, row.doctype, row.name);\n        });\n    }\n}\n\nfunction set_row_value_options(frm, cdt, cdn) {\n    var row = locals[cdt][cdn];\n    \n    if (!row.property) {\n        return;\n    }\n\n    // Determine target DocType based on selected Property\n    var target_doctype = \"\";\n    \n    switch(row.property) {\n        case \"Department\":\n            target_doctype = \"Department\";\n            break;\n        case \"Designation\":\n            target_doctype = \"Designation\";\n            break;\n        case \"Employment Type\":\n            target_doctype = \"Employment Type\";\n            break;\n        case \"Reports to\":\n            target_doctype = \"Employee\";\n            break;\n        default:\n            target_doctype = \"\";\n    }\n\n    if (target_doctype) {\n        // Fetch values dynamically from target DocType and populate dropdown options\n        frappe.call({\n            method: \"frappe.client.get_list\",\n            args: {\n                doctype: target_doctype,\n                fields: [\"name\"],\n                limit_page_length: 0,\n                order_by: \"name asc\"\n            },\n            callback: function(r) {\n                if (r.message) {\n                    var options = r.message.map(function(item) {\n                        return item.name;\n                    });\n                    \n                    // Set select options specifically for the 'new_value' field in this grid row\n                    var field = frappe.utils.get_grid_field(cdt, cdn, 'new_value'); // Replace new_value with actual fieldname\n                    if (field) {\n                        field.df.options = [\"\"].concat(options);\n                        frm.fields_dict.properties.grid.refresh_field('new_value');\n                    }\n                }\n            }\n        });\n    }\n}\n",
		},
		{
			"name": "Employee Record Update Request",
			"dt": "Employee Record Update Request",
			"view": "Form",
			"enabled": 0,
			"script": "// Mapping of user-facing Property labels to actual field names on the Employee DocType\r\nconst PROPERTY_FIELD_MAP = {\r\n\t\"Department\": \"department\",\r\n\t\"Designation\": \"designation\",\r\n\t\"Day Off Category\": \"holiday_list\",\r\n\t\"Number of Days Off\": \"notice_number_of_days\",\r\n\t\"Employment Type\": \"employment_type\",\r\n\t\"Reports to\": \"reports_to\",\r\n\r\n};\r\n\r\nfrappe.ui.form.on(\"Employee Record Update Request\", {\r\n\trefresh(frm) {\r\n\t\t// Re-apply field definitions when form loads or renders grid rows\r\n\t\tset_child_table_fieldtypes(frm);\r\n\t},\r\n\r\n\temployee(frm) {\r\n\t\t// When employee is changed, refresh existing rows to update Current Details\r\n\t\tif (frm.doc.properties && frm.doc.properties.length) {\r\n\t\t\tfrm.doc.properties.forEach((row) => {\r\n\t\t\t\tupdate_property_row(frm, row.doctype, row.name);\r\n\t\t\t});\r\n\t\t}\r\n\t}\r\n});\r\n\r\nfrappe.ui.form.on(\"Employee Record Update Request Properties Item\", {\r\n\tproperty(frm, cdt, cdn) {\r\n\t\tupdate_property_row(frm, cdt, cdn);\r\n\t},\r\n\r\n\tproperties_add(frm, cdt, cdn) {\r\n\t\t// Ensure fresh field configurations on new row creation\r\n\t\tset_child_table_fieldtypes(frm);\r\n\t}\r\n});\r\n\r\n/**\r\n * Updates old_value, field type, options, and clears new_value when property changes\r\n */\r\nfunction update_property_row(frm, cdt, cdn) {\r\n\tlet row = frappe.get_doc(cdt, cdn);\r\n\r\n\t// Case 1: Empty property option selected -> Clear values\r\n\tif (!row.property) {\r\n\t\tfrappe.model.set_value(cdt, cdn, {\r\n\t\t\told_value: \"\",\r\n\t\t\tnew_value: \"\",\r\n\t\t\tnew_value_doctype: \"\"\r\n\t\t});\r\n\t\treturn;\r\n\t}\r\n\r\n\tlet employee_fieldname = PROPERTY_FIELD_MAP[row.property];\r\n\r\n\tif (!employee_fieldname) {\r\n\t\t// Fallback: convert Property label to snake_case if missing from map\r\n\t\temployee_fieldname = row.property.toLowerCase().replace(/ /g, \"_\");\r\n\t}\r\n\r\n\t// Retrieve Employee meta to check field definition\r\n\tlet emp_meta = frappe.get_meta(\"Employee\");\r\n\tlet field_df = emp_meta.fields.find(f => f.fieldname === employee_fieldname);\r\n\r\n\t// Configure Dynamic Link target or metadata if field is a Link\r\n\tif (field_df && field_df.fieldtype === \"Link\") {\r\n\t\tfrappe.model.set_value(cdt, cdn, \"new_value_doctype\", field_df.options);\r\n\t} else {\r\n\t\tfrappe.model.set_value(cdt, cdn, \"new_value_doctype\", \"\");\r\n\t}\r\n\r\n\t// Fetch current value from linked Employee in parent form\r\n\tif (frm.doc.employee) {\r\n\t\tfrappe.db.get_value(\"Employee\", frm.doc.employee, employee_fieldname)\r\n\t\t\t.then(r => {\r\n\t\t\t\tlet current_val = (r && r.message) ? r.message[employee_fieldname] : \"\";\r\n\t\t\t\tfrappe.model.set_value(cdt, cdn, \"old_value\", current_val || \"\");\r\n\t\t\t});\r\n\t} else {\r\n\t\tfrappe.model.set_value(cdt, cdn, \"old_value\", \"\");\r\n\t}\r\n\r\n\t// Clear invalid previous selection when property changes\r\n\tfrappe.model.set_value(cdt, cdn, \"new_value\", \"\");\r\n\r\n\t// Apply field options and types dynamically across grid UI\r\n\tset_child_table_fieldtypes(frm);\r\n}\r\n\r\n/**\r\n * Dynamically updates field definitions (Select options, Link queries, dynamic behavior)\r\n */\r\nfunction set_child_table_fieldtypes(frm) {\r\n\tlet emp_meta = frappe.get_meta(\"Employee\");\r\n\r\n\tfrm.fields_dict[\"properties\"].grid.get_field(\"new_value\").get_query = function(doc, cdt, cdn) {\r\n\t\tlet row = frappe.get_doc(cdt, cdn);\r\n\t\tlet employee_fieldname = PROPERTY_FIELD_MAP[row.property];\r\n\t\tlet field_df = emp_meta.fields.find(f => f.fieldname === employee_fieldname);\r\n\r\n\t\tif (field_df && field_df.fieldtype === \"Select\") {\r\n\t\t\t// Parse Select options split by newline\r\n\t\t\tlet options = (field_df.options || \"\").split(\"\\n\").filter(Boolean);\r\n\t\t\treturn {\r\n\t\t\t\tfilters: [\r\n\t\t\t\t\t[\"name\", \"in\", options]\r\n\t\t\t\t]\r\n\t\t\t};\r\n\t\t}\r\n\t\treturn {};\r\n\t};\r\n}",
		},
		{
			"name": "Testing new details fetech",
			"dt": "Employee Record Update Request",
			"view": "Form",
			"enabled": 1,
			"script": "frappe.ui.form.on(\"Employee Record Update Request\", {\n    employee(frm) {\n        if (!frm.doc.employee) {\n            frm.set_value(\"current_salary_structure\", \"\");\n            frm.set_value(\"current_base_salary\", 0);\n            frm.set_value(\"line_manager\", \"\");\n            return;\n        }\n\n        frappe.call({\n            method: \"frappe.client.get_list\",\n            args: {\n                doctype: \"Salary Structure Assignment\",\n                filters: {\n                    employee: frm.doc.employee,\n                    docstatus: 1\n                },\n                fields: [\"salary_structure\", \"base\"],\n                order_by: \"from_date desc, creation desc\",\n                limit_page_length: 1\n            },\n            callback(r) {\n                const rows = r.message || [];\n                if (rows.length) {\n                    frm.set_value(\"current_salary_structure\", rows[0].salary_structure || \"\");\n                    frm.set_value(\"current_base_salary\", rows[0].base || 0);\n                } else {\n                    frm.set_value(\"current_salary_structure\", \"\");\n                    frm.set_value(\"current_base_salary\", 0);\n                    frappe.msgprint(__(\"No submitted Salary Structure Assignment was found for this employee.\"));\n                }\n            }\n        });\n\n        frappe.db.get_value(\"Employee\", frm.doc.employee, \"department\").then((emp) => {\n            const department = (emp.message || {}).department;\n            if (!department) {\n                frm.set_value(\"line_manager\", \"\");\n                frappe.msgprint(__(\"This employee has no department, so the Line Manager could not be set.\"));\n                return;\n            }\n            frappe.db.get_value(\"Department\", department, \"custom_department_head\").then((dept) => {\n                const head = (dept.message || {}).custom_department_head;\n                if (head) {\n                    frm.set_value(\"line_manager\", head);\n                } else {\n                    frm.set_value(\"line_manager\", \"\");\n                    frappe.msgprint(__(\"No Department Head is set on the department of this employee.\"));\n                }\n            });\n        });\n    },\n\n    before_submit(frm) {\n        const selected = [];\n        if (frm.doc.salary_update_required) {\n            selected.push(__(\"Salary Update Required\"));\n        }\n        if (frm.doc.term_changes_required) {\n            selected.push(__(\"Terms Changes Required\"));\n        }\n        if (frm.doc.day_off_terms_required) {\n            selected.push(__(\"Day Off Terms Required\"));\n        }\n        if (frm.doc.benefits_changes_required) {\n            selected.push(__(\"Benefits Changes Required\"));\n        }\n        if (selected.length) {\n            frappe.throw(__(\"This request cannot be submitted while the following is selected: {0}\", [selected.join(\", \")]));\n        }\n    }\n});\n\nfrappe.ui.form.on(\"Employee Record Update Request\", {\n    refresh(frm) {\n        update_line_manager_visibility(frm);\n    },\n\n    employee(frm) {\n        update_line_manager_visibility(frm);\n    }\n});\n\nfunction update_line_manager_visibility(frm) {\n    frm.toggle_display(\"reports_to\", true);\n\n    if (!frm.doc.employee) {\n        frm.toggle_display(\"line_manager\", true);\n        return;\n    }\n\n    frappe.db.get_value(\"Employee\", frm.doc.employee, \"user_id\").then((emp) => {\n        const user = (emp.message || {}).user_id;\n        if (!user) {\n            frm.toggle_display(\"line_manager\", true);\n            return;\n        }\n        frappe.db.get_value(\"Department\", { custom_department_head: user }, \"name\").then((dept) => {\n            const is_head = !!(dept.message && dept.message.name);\n            frm.toggle_display(\"line_manager\", !is_head);\n            frm.toggle_display(\"reports_to\", true);\n        });\n    });\n}\n\nfrappe.ui.form.on(\"Employee Record Update Request Properties Item\", {\n    async terms(frm, cdt, cdn) {\n        const row = locals[cdt][cdn];\n\n        // Clear previous values\n        await frappe.model.set_value(cdt, cdn, \"new_value\", \"\");\n        await frappe.model.set_value(cdt, cdn, \"new_value_doctype\", \"\");\n        await frappe.model.set_value(cdt, cdn, \"old_value\", \"\");\n\n        if (!row.terms) {\n            frm.refresh_field(\"employment_terms\");\n            return;\n        }\n\n        const r = await frappe.db.get_value(\n            \"Record Update Property\",\n            row.terms,\n            [\"linked_doctype\", \"employee_field\"]\n        );\n\n        const p = r.message || {};\n\n        if (!p.linked_doctype) {\n            frappe.msgprint(__(\"Linked DocType is not configured for this Term.\"));\n            return;\n        }\n\n        // Set Dynamic Link reference DocType\n        await frappe.model.set_value(cdt, cdn, \"new_value_doctype\", p.linked_doctype);\n\n        // Fetch existing Employee value\n        if (frm.doc.employee && p.employee_field) {\n            const res = await frappe.db.get_value(\n                \"Employee\",\n                frm.doc.employee,\n                p.employee_field\n            );\n\n            await frappe.model.set_value(\n                cdt,\n                cdn,\n                \"old_value\",\n                (res.message || {})[p.employee_field] || \"\"\n            );\n        }\n\n        // Refresh child table & Dynamic Link fields\n        frm.refresh_field(\"employment_terms\");\n\n        const grid_row = frm.fields_dict.employment_terms.grid.grid_rows_by_docname[cdn];\n        if (grid_row) {\n            grid_row.refresh_field(\"new_value_doctype\");\n            grid_row.refresh_field(\"new_value\");\n        }\n    }\n});\n",
		},
	]
